import sys
from collections import deque

def bfs(graph, source, sink, parent):
    visited = [False] * len(graph)
    queue = deque([source])
    visited[source] = True
    while queue:
        u = queue.popleft()
        for v, capacity in graph[u]:
            if not visited[v] and capacity > 0:
                visited[v] = True
                parent[v] = (u, len(graph[u]))
                if v == sink:
                    return True
                queue.append(v)
    return False

def edmonds_karp(capacity_matrix, n, source, sink):
    flow = 0
    adj = [[] for _ in range(n)]
    for i in range(n):
        for j in range(n):
            if capacity_matrix[i][j] > 0:
                adj[i].append((j, capacity_matrix[i][j]))

    while True:
        parent = [-1] * n
        if not bfs(adj, source, sink, parent):
            break

        path_flow = float('inf')
        s = sink
        while s != source:
            p, idx = parent[s]
            cap = 0
            for v, c in adj[p]:
                if v == s:
                    cap = c
                    break
            path_flow = min(path_flow, cap)
            s = p

        flow += path_flow
        s = sink
        while s != source:
            p = parent[s][0]
            for i, (v, c) in enumerate(adj[p]):
                if v == s:
                    adj[p][i] = (v, c - path_flow)
                    break
            for i, (v, c) in enumerate(adj[s]):
                if v == p:
                    adj[s][i] = (v, c + path_flow)
                    break
            s = p

    return flow

def main():
    input_data = sys.stdin.read().split()
    if not input_data:
        return
    iterator = iter(input_data)
    n = int(next(iterator))
    k = int(next(iterator))

    matrix = []
    for _ in range(n):
        row = []
        for _ in range(n):
            row.append(int(next(iterator)))
        matrix.append(row)

    max_flow = 0
    added = 0

    while added <= k:
        current_flow = edmonds_karp(matrix, n, 0, n - 1)
        if current_flow == 0:
            break
        if added + current_flow > k:
            break
        added += current_flow
        max_flow += current_flow

        for i in range(n):
            for j in range(n):
                if matrix[i][j] > 0 and matrix[i][j] < float('inf'):
                    pass
                else:
                    continue

        new_matrix = [row[:] for row in matrix]
        for i in range(n):
            for j in range(n): new_matrix[i][j] = matrix[i][j]

        temp_flow = edmonds_karp(new_matrix, n, 0, n - 1)
        if temp_flow > 0:
            if added + temp_flow <= k:
                added += temp_flow
                max_flow += temp_flow
                for i in range(n):
                    for j in range(n):
                        matrix[i][j] = new_matrix[i][j]
            else:
                break
        else:
            break

    print(max_flow)

if __name__ == "__main__":
    main()
